# Generates il-01..il-12 (light + dark) from one source so palette, ground shadow, stroke and radius rules can't drift.
# Rules (AC-VD-06): flat fills, palette-only (no skin tones/photos), 240x240 canvas, faceless figures, one amber accent, no text in art.
import sys
out = sys.argv[1]
L = dict(ink='#193957', mid='#29537A', blue='#3C75AA', soft='#89AFD2', wash='#E1EBF4', paper='#FFFFFF', line='#E4E0D4', amber='#E38B29',
         green='#3A7D5C', red='#B23A2E', ground='rgba(60,117,170,.10)', glass='#FFFFFF', head='#E1EBF4', cream='#F6F4EE')
D = dict(ink='#89AFD2', mid='#3C75AA', blue='#4A7FB0', soft='#89AFD2', wash='#1B2937', paper='#1E2328', line='#2C343A', amber='#E38B29',
         green='#8FC9A8', red='#E8968E', ground='rgba(0,0,0,.28)', glass='#1E2328', head='#2B3A49', cream='#14181B')
def wrap(body, P, title):
    return f'<svg xmlns="http://www.w3.org/2000/svg" width="240" height="240" viewBox="0 0 240 240" role="img" aria-label="{title}">\n  <ellipse cx="120" cy="212" rx="86" ry="11" fill="{P["ground"]}"/>\n{body}</svg>\n'
def person(P, x, y, shirt=None, hat=False):
    shirt = shirt or P['mid']
    s = f'<rect x="{x-24}" y="{y+34}" width="48" height="64" rx="18" fill="{shirt}"/>'
    s += f'<circle cx="{x}" cy="{y+16}" r="17" fill="{P["head"]}"/>'
    s += f'<path d="M{x-17} {y+14}a17 17 0 0 1 34 0c-8-7-18-6-23-11-3 5-7 9-11 11Z" fill="{P["ink"]}"/>'
    if hat: s += f'<path d="M{x-20} {y+10}h40v-3a20 20 0 0 0-40 0Z" fill="{P["blue"]}"/><rect x="{x-22}" y="{y+8}" width="44" height="5" rx="2.5" fill="{P["ink"]}"/>'
    return s
def house(P, x, y, door=True):
    s = f'<rect x="{x}" y="{y+34}" width="84" height="64" rx="6" fill="{P["wash"]}"/>'
    s += f'<path d="M{x-8} {y+40}L{x+42} {y}l50 40Z" fill="{P["blue"]}"/><rect x="{x+60}" y="{y+8}" width="10" height="20" rx="2" fill="{P["mid"]}"/>'
    if door: s += f'<rect x="{x+28}" y="{y+58}" width="26" height="40" rx="4" fill="{P["amber"]}"/>'
    s += f'<rect x="{x+60}" y="{y+52}" width="16" height="16" rx="3" fill="{P["paper"]}"/>'
    return s
IL = {}
IL['01'] = ('Homeowner posting a job', lambda P: house(P,112,70) + person(P,72,60) + f'<rect x="92" y="122" width="20" height="32" rx="4" fill="{P["ink"]}" transform="rotate(-10 102 138)"/><rect x="96" y="128" width="12" height="18" rx="2" fill="{P["amber"]}" transform="rotate(-10 102 138)"/>')
IL['02'] = ('Messages', lambda P: f'<rect x="44" y="52" width="108" height="76" rx="22" fill="{P["ink"] if P is L else P["mid"]}"/><path d="M62 124l-6 24 28-18Z" fill="{P["ink"] if P is L else P["mid"]}"/>' + ''.join(f'<circle cx="{82+i*22}" cy="90" r="6" fill="{P["amber"] if i==1 else P["soft"]}"/>' for i in range(3)) + f'<rect x="96" y="118" width="100" height="64" rx="20" fill="{P["paper"]}" stroke="{P["line"]}" stroke-width="3"/><path d="M178 178l8 22-26-16Z" fill="{P["paper"]}" stroke="{P["line"]}" stroke-width="3" stroke-linejoin="round"/><rect x="114" y="140" width="50" height="8" rx="4" fill="{P["wash"]}"/><rect x="114" y="156" width="34" height="8" rx="4" fill="{P["wash"]}"/>')
IL['03'] = ('Time expired', lambda P: f'<circle cx="116" cy="112" r="62" fill="{P["paper"]}" stroke="{P["ink"]}" stroke-width="9"/><path d="M116 70v44l28 18" fill="none" stroke="{P["ink"]}" stroke-width="9" stroke-linecap="round" stroke-linejoin="round"/><circle cx="116" cy="114" r="6" fill="{P["amber"]}"/><circle cx="170" cy="158" r="24" fill="{P["amber"]}"/><path d="M160 148l20 20M180 148l-20 20" stroke="#241300" stroke-width="7" stroke-linecap="round"/><path d="M92 44l-12-14M140 44l12-14" stroke="{P["soft"]}" stroke-width="7" stroke-linecap="round"/>')
IL['04'] = ('Not found', lambda P: f'<rect x="46" y="132" width="148" height="54" rx="14" fill="{P["wash"]}"/><path d="M46 156c26-16 38 14 62 0s40-14 86 0" fill="none" stroke="{P["soft"]}" stroke-width="7" stroke-linecap="round"/><path d="M120 40c-26 0-46 19-46 44 0 32 46 72 46 72s46-40 46-72c0-25-20-44-46-44Z" fill="{P["paper"]}" stroke="{P["ink"]}" stroke-width="9" stroke-linejoin="round"/><path d="M107 78c0-17 26-17 26 0 0 11-13 11-13 24" fill="none" stroke="{P["ink"]}" stroke-width="8" stroke-linecap="round"/><circle cx="120" cy="116" r="5.5" fill="{P["amber"]}"/>')
IL['05'] = ('Unavailable', lambda P: f'<rect x="48" y="58" width="130" height="116" rx="18" fill="{P["paper"]}" stroke="{P["mid"]}" stroke-width="8"/><path d="M48 92h130" stroke="{P["mid"]}" stroke-width="8"/><path d="M76 46v22M150 46v22" stroke="{P["mid"]}" stroke-width="8" stroke-linecap="round"/>' + ''.join(f'<rect x="{66+c*34}" y="{108+r*26}" width="20" height="16" rx="4" fill="{P["wash"]}"/>' for r in range(2) for c in range(3) if (r,c)!=(0,2)) + f'<path d="M158 110l14 14M172 110l-14 14" stroke="{P["red"]}" stroke-width="6" stroke-linecap="round"/><circle cx="170" cy="164" r="30" fill="{P["paper"]}" stroke="{P["ink"]}" stroke-width="8"/><path d="M170 146v18l12 8" fill="none" stroke="{P["ink"]}" stroke-width="7" stroke-linecap="round"/>')
IL['06'] = ('Rating', lambda P: f'<path d="M120 36l22 46 50 7-36 35 9 50-45-24-45 24 9-50-36-35 50-7Z" fill="{P["amber"]}" stroke="{P["amber"]}" stroke-width="10" stroke-linejoin="round"/><path d="M120 62l12 26 28 4-20 20 5 28-25-14-25 14 5-28-20-20 28-4Z" fill="#EB9A3F" opacity=".7"/><path d="M44 62v18M35 71h18" stroke="{P["soft"]}" stroke-width="5" stroke-linecap="round"/><circle cx="198" cy="150" r="5" fill="{P["blue"]}"/><circle cx="50" cy="150" r="4" fill="{P["soft"]}"/>')
IL['07'] = ('Verified credentials', lambda P: f'<path d="M120 34l66 22v50c0 40-28 66-66 82-38-16-66-42-66-82V56Z" fill="{P["ink"] if P is L else P["mid"]}"/><path d="M120 50l50 17v39c0 31-21 52-50 66-29-14-50-35-50-66V67Z" fill="{P["blue"]}"/><circle cx="120" cy="108" r="30" fill="{P["green"]}"/><path d="M104 108l11 11 21-23" fill="none" stroke="{"#FFFFFF" if P is L else "#14181B"}" stroke-width="8" stroke-linecap="round" stroke-linejoin="round"/><circle cx="188" cy="62" r="9" fill="{P["amber"]}"/><path d="M52 66v14M45 73h14" stroke="{P["soft"]}" stroke-width="5" stroke-linecap="round"/>')
IL['08'] = ('Tradie at work', lambda P: person(P,100,50,shirt=P["mid"],hat=True) + f'<rect x="76" y="118" width="48" height="10" rx="3" fill="{P["amber"]}"/><rect x="76" y="132" width="48" height="52" rx="6" fill="{P["mid"]}"/><path d="M74 100c-12 6-18 20-18 36h14v-26Z" fill="{P["mid"]}"/><path d="M126 100c14 6 20 18 22 34" fill="none" stroke="{P["mid"]}" stroke-width="16" stroke-linecap="round"/><g transform="rotate(32 154 130)"><rect x="150" y="104" width="8" height="52" rx="4" fill="{P["soft"]}"/><circle cx="154" cy="100" r="13" fill="none" stroke="{P["soft"]}" stroke-width="8"/></g><circle cx="190" cy="66" r="26" fill="{P["wash"]}"/><path d="M180 66h20" stroke="{P["blue"]}" stroke-width="6" stroke-linecap="round"/>')
IL['09'] = ('Offline', lambda P: f'<path d="M72 150a34 34 0 0 1 4-68 48 48 0 0 1 90-4 36 36 0 0 1 6 72Z" fill="{P["wash"]}" stroke="{P["ink"]}" stroke-width="8" stroke-linejoin="round"/><path d="M58 52l124 124" stroke="{P["paper"]}" stroke-width="22" stroke-linecap="round"/><path d="M58 52l124 124" stroke="{P["amber"]}" stroke-width="9" stroke-linecap="round"/><circle cx="196" cy="60" r="5" fill="{P["soft"]}"/><circle cx="48" cy="140" r="4" fill="{P["blue"]}"/>')
IL['10'] = ('Location access', lambda P: ''.join(f'<circle cx="120" cy="150" r="{r}" fill="none" stroke="{P["soft"]}" stroke-opacity="{o}" stroke-width="5"/>' for r,o in ((78,.35),(54,.6))) + f'<path d="M120 36c-24 0-42 17-42 40 0 30 42 66 42 66s42-36 42-66c0-23-18-40-42-40Z" fill="{P["blue"]}"/><circle cx="120" cy="76" r="15" fill="{P["paper"]}"/><circle cx="120" cy="76" r="6.5" fill="{P["amber"]}"/><ellipse cx="120" cy="150" rx="22" ry="7" fill="{P["ink"]}" opacity=".25"/>')
IL['11'] = ('Notifications', lambda P: f'<path d="M120 44c-30 0-48 22-48 52v28l-14 24h124l-14-24V96c0-30-18-52-48-52Z" fill="{P["blue"]}"/><path d="M120 44c-30 0-48 22-48 52v28l-14 24h62Z" fill="{P["mid"]}" opacity=".5"/><path d="M104 160a16 16 0 0 0 32 0Z" fill="{P["ink"]}"/><circle cx="120" cy="36" r="9" fill="{P["ink"]}"/><circle cx="170" cy="70" r="20" fill="{P["amber"]}"/><path d="M170 60v12" stroke="#241300" stroke-width="6" stroke-linecap="round"/><circle cx="170" cy="80" r="3.5" fill="#241300"/>')
IL['12'] = ('Payment receipt', lambda P: f'<path d="M68 38h104v136l-13-9-13 9-13-9-13 9-13-9-13 9-13-9-13 9Z" fill="{P["paper"]}" stroke="{P["ink"]}" stroke-width="8" stroke-linejoin="round"/>' + ''.join(f'<rect x="88" y="{64+i*22}" width="{60-i*10}" height="8" rx="4" fill="{P["wash"]}"/>' for i in range(3)) + f'<rect x="88" y="132" width="64" height="10" rx="5" fill="{P["ink"]}"/><circle cx="170" cy="168" r="28" fill="{P["amber"]}"/><circle cx="170" cy="168" r="15" fill="none" stroke="#241300" stroke-width="6"/><path d="M164 168h12" stroke="#241300" stroke-width="6" stroke-linecap="round"/>')
for k,(title,fn) in IL.items():
    for n,P in (('light',L),('dark',D)):
        open(f'{out}/il-{k}-{n}.svg','w').write(wrap(fn(P),P,title))
print(len(IL)*2,'illustrations')
